<?php namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\{Company,Opportunity,Activity,Bid};class DashboardController extends Controller{public function __invoke(){return ['total_companies'=>Company::count(),'high_priority'=>Company::where('priority','Alta')->count(),'active_opportunities'=>Opportunity::whereNotIn('status',['Ganha','Perdida'])->count(),'potential_value'=>(float)Opportunity::whereNotIn('status',['Perdida'])->sum('potential_value'),'overdue_activities'=>Activity::where('status','Pendente')->where('scheduled_at','<',now())->count(),'monitored_bids'=>Bid::where('status','Monitorada')->count(),'paraguay_companies'=>Company::whereRaw("lower(country) like '%paraguai%'")->count(),'top_opportunities'=>Opportunity::with('company')->orderByDesc('score')->limit(8)->get(),'next_activities'=>Activity::with('company')->where('status','Pendente')->where('scheduled_at','>=',now())->orderBy('scheduled_at')->limit(6)->get()];}}
